24: /// Configuration parameters for launching the offline Axum server.
25: #[derive(Debug, Clone)]
26: pub struct ServerConfig {
27:     /// IP address or interface to bind (e.g., "127.0.0.1" for localhost, "0.0.0.0" for LAN).
28:     pub host: String,
29:     /// TCP port to bind (default: 8080).
30:     pub port: u16,
31:     /// Whether to automatically open the default web browser upon launch.
32:     pub open_browser: bool,
33:     /// Optional path to an MBTiles vector/raster basemap SQLite archive.
34:     pub mbtiles_path: Option<PathBuf>,
35:     /// Optional directory containing extracted offline map tiles (`{z}/{x}/{y}.png`).
36:     pub tile_dir: Option<PathBuf>,
37:     /// Pre-loaded flight dataset (e.g. provided via CLI argument `flightreader serve <FILE>`).
38:     pub initial_dataset: Option<FlightDataset>,
39: }
40: 
41: impl Default for ServerConfig {
42:     fn default() -> Self {
43:         Self {
44:             host: "127.0.0.1".to_string(),
45:             port: 8080,
46:             open_browser: false,
47:             mbtiles_path: None,
48:             tile_dir: None,
49:             initial_dataset: None,
50:         }
51:     }
52: }
53: 
54: /// Starts the HTTP and WebSocket server with default state initialized from config.
55: pub async fn start_server(config: ServerConfig) -> Result<(), ServerError> {
56:     let state = AppState::new(config.clone());
57:     start_server_with_state(config, state).await
58: }
59: 
60: /// Starts the HTTP and WebSocket server with explicit pre-existing shared state.
61: pub async fn start_server_with_state(
62:     config: ServerConfig,
63:     state: AppState,
64: ) -> Result<(), ServerError> {
65:     let addr = format!("{}:{}", config.host, config.port);
66:     let listener = tokio::net::TcpListener::bind(&addr).await?;
67:     tracing::info!("OpenFlightReader server listening on http://{}", addr);
68: 
69:     let app = build_app(state);
70: 
71:     axum::serve(listener, app)
72:         .with_graceful_shutdown(shutdown_signal())
73:         .await?;
74: 
75:     tracing::info!("Server shut down gracefully");
76:     Ok(())
77: }
78: 
79: async fn shutdown_signal() {
80:     let _ = tokio::signal::ctrl_c().await;
81:     tracing::info!("Received Ctrl-C signal, initiating graceful shutdown...");
82: }
