27: impl AppState {
28:     /// Creates a new `AppState` instance initialized from the given configuration.
29:     pub fn new(config: ServerConfig) -> Self {
30:         let (ws_broadcaster, _) = broadcast::channel(128);
31:         let dataset = Arc::new(RwLock::new(config.initial_dataset.clone()));
32:         let ws_broadcast = ws_broadcaster.clone();
33: 
34:         Self {
35:             dataset,
36:             config: Arc::new(config),
