1: //! Flight log upload endpoint supporting multipart forms and raw binary streams.
2: 
3: use axum::{
4:     extract::{FromRequest, Request, State},
5:     http::header::CONTENT_TYPE,
6:     Json,
7: };
8: use serde::Serialize;
9: 
10: use flightreader_export::model::FlightMetadata;
11: 
12: use crate::error::ServerError;
13: use crate::state::AppState;
14: 
15: /// Upload success response payload.
16: #[derive(Debug, Serialize)]
17: pub struct UploadResponse {
18:     /// Status indicator ("success").
19:     pub status: &'static str,
20:     /// Informational message.
21:     pub message: String,
22:     /// Detected log format identifier.
23:     pub log_type: String,
24:     /// Total count of synchronized telemetry points extracted.
25:     pub records_count: usize,
26:     /// Total recording duration in seconds.
27:     pub duration_seconds: f64,
28:     /// Extracted flight metadata.
29:     pub metadata: FlightMetadata,
30: }
31: 
32: /// Handler for `POST /api/v1/upload`.
33: pub async fn upload_flight_log(
34:     State(state): State<AppState>,
35:     req: Request,
36: ) -> Result<Json<UploadResponse>, ServerError> {
37:     let content_type = req
38:         .headers()
39:         .get(CONTENT_TYPE)
40:         .and_then(|v| v.to_str().ok())
41:         .unwrap_or("")
42:         .to_string();
43: 
44:     let raw_bytes: Vec<u8> = if content_type.starts_with("multipart/form-data") {
45:         let mut multipart = axum::extract::Multipart::from_request(req, &state)
46:             .await
47:             .map_err(|e| ServerError::Multipart(e.to_string()))?;
48: 
49:         let mut extracted = Vec::new();
50:         while let Some(field) = multipart
51:             .next_field()
52:             .await
53:             .map_err(|e| ServerError::Multipart(e.to_string()))?
54:         {
55:             let data = field
56:                 .bytes()
57:                 .await
58:                 .map_err(|e| ServerError::Multipart(e.to_string()))?;
59:             if !data.is_empty() {
60:                 extracted = data.to_vec();
61:                 break;
62:             }
63:         }
64: 
65:         if extracted.is_empty() {
66:             return Err(ServerError::BadRequest(
67:                 "No valid file payload found in multipart upload".to_string(),
68:             ));
69:         }
70:         extracted
71:     } else {
72:         // Raw binary direct payload
73:         let body_bytes = axum::body::to_bytes(req.into_body(), 256 * 1024 * 1024)
74:             .await
75:             .map_err(|e| ServerError::BadRequest(e.to_string()))?;
76:         body_bytes.to_vec()
77:     };
78: 
79:     if raw_bytes.is_empty() {
80:         return Err(ServerError::BadRequest(
81:             "Uploaded flight log payload is empty".to_string(),
82:         ));
83:     }
84: 
85:     // Minimum header length validation
86:     if raw_bytes[0] == flightreader_core::dat::DAT_MAGIC {
87:         if raw_bytes.len() < 9 {
88:             return Err(ServerError::BadRequest(
89:                 "Truncated .DAT header: expected at least 9 bytes".to_string(),
90:             ));
91:         }
92:     } else if raw_bytes.len() < 100 {
93:         return Err(ServerError::BadRequest(
94:             "Truncated DJI .txt header: expected at least 100 bytes".to_string(),
95:         ));
96:     }
97: 
98:     // Ingest and aggregate via flightreader-export engine
99:     let dataset = flightreader_export::aggregate_buffer(&raw_bytes, None)
100:         .map_err(ServerError::Export)?;
101: 
102:     let records_count = dataset.points.len();
103:     let duration_seconds = dataset.metadata.duration_seconds;
104:     let log_type = dataset.metadata.log_type.clone();
105:     let metadata = dataset.metadata.clone();
106: 
107:     // Atomically swap dataset in AppState and notify WebSocket subscribers
108:     state.set_dataset(dataset).await;
109: 
110:     Ok(Json(UploadResponse {
111:         status: "success",
112:         message: format!(
113:             "Successfully parsed and loaded {} ({} telemetry points)",
114:             log_type, records_count
115:         ),
116:         log_type,
117:         records_count,
118:         duration_seconds,
119:         metadata,
120:     }))
121: }
