154: async fn handle_ws_socket(socket: WebSocket, state: AppState) {
155:     let (mut ws_sender, mut ws_receiver) = socket.split();
156:     let mut broadcast_rx = state.ws_broadcaster.subscribe();
157: 
158:     // Outbound task: forward broadcast messages to this WebSocket client
159:     let mut send_task = tokio::spawn(async move {
160:         while let Ok(msg) = broadcast_rx.recv().await {
161:             if let Ok(json_str) = serde_json::to_string(&msg) {
162:                 if ws_sender.send(Message::Text(json_str)).await.is_err() {
163:                     break;
164:                 }
165:             }
166:         }
167:     });
168: 
169:     // Inbound task: receive client commands and process seeks/pings
170:     let broadcaster = state.ws_broadcaster.clone();
171:     let state_clone = state.clone();
172: 
173:     let mut recv_task = tokio::spawn(async move {
174:         while let Some(Ok(message)) = ws_receiver.next().await {
175:             match message {
176:                 Message::Text(text) => {
177:                     // Try parsing as structured WsClientMessage
178:                     if let Ok(cmd) = serde_json::from_str::<WsClientMessage>(&text) {
179:                         match cmd {
180:                             WsClientMessage::Seek { index } | WsClientMessage::Scrub { index, .. } => {
181:                                 handle_seek(index, &state_clone, &broadcaster).await;
182:                             }
183:                             WsClientMessage::SeekTime { elapsed_s } => {
184:                                 handle_seek_time(elapsed_s, &state_clone, &broadcaster).await;
185:                             }
186:                             WsClientMessage::Playback {
187:                                 playing,
188:                                 speed,
189:                                 current_index,
190:                             } => {
191:                                 let _ = broadcaster.send(WsServerMessage::Playback {
192:                                     playing,
193:                                     speed,
194:                                     current_index,
195:                                 });
196:                             }
197:                             WsClientMessage::Ping => {
198:                                 let _ = broadcaster.send(WsServerMessage::Pong);
199:                             }
200:                         }
201:                     } else if let Ok(val) = serde_json::from_str::<serde_json::Value>(&text) {
202:                         // Resilient fallback for alternative JSON shapes
203:                         if let Some(action) = val.get("action").and_then(|v| v.as_str()) {
204:                             match action {
205:                                 "seek" => {
206:                                     if let Some(idx) = val.get("index").and_then(|v| v.as_u64()) {
