210:                                 "play" | "pause" => {
211:                                     let playing = action == "play";
212:                                     let speed = val.get("speed").and_then(|v| v.as_f64()).unwrap_or(1.0);
213:                                     let idx = val.get("index").and_then(|v| v.as_u64()).unwrap_or(0) as usize;
214:                                     let _ = broadcaster.send(WsServerMessage::Playback {
215:                                         playing,
216:                                         speed,
217:                                         current_index: idx,
218:                                     });
219:                                 }
220:                                 _ => {}
221:                             }
222:                         }
223:                     }
224:                 }
225:                 Message::Close(_) => break,
226:                 _ => {}
227:             }
228:         }
229:     });
