//! Empirical adversarial challenge and stress harness for `flightreader-server`.
//!
//! Stress-tests:
//! 1. Rapid WebSocket timeline scrubbing and broadcast queue behavior.
//! 2. Multi-client fan-out and concurrent scrubber interaction.
//! 3. Boundary datasets: 0 points (empty), 1 point (single-point), negative altitudes.
//! 4. Out-of-bounds scrubber seeks and invalid types.
//! 5. Ingestion stress: truncated headers (<9 bytes DAT, <100 bytes TXT), corrupt packets, malformed multipart forms.
//! 6. Extreme query parameters on REST endpoints.

use axum::body::Body;
use axum::http::{header, Request, StatusCode};
use futures_util::{SinkExt, StreamExt};
use http_body_util::BodyExt;
use serde_json::Value;
use tokio_tungstenite::connect_async;
use tokio_tungstenite::tungstenite::Message;
use tower::ServiceExt;

use flightreader_export::model::{
    FlightDataset, FlightEvent, FlightEventType, FlightMetadata, TelemetryPoint,
};
use flightreader_server::routes::build_app;
use flightreader_server::routes::flight::{ColumnarPointsResponse, FlightInfoResponse};
use flightreader_server::routes::ws::WsServerMessage;
use flightreader_server::state::AppState;

/// Shared helper creating a canonical 600-point mock flight dataset.
fn mock_canonical_dataset() -> FlightDataset {
    let mut points = Vec::with_capacity(600);
    for i in 0..600 {
        let elapsed_s = i as f64 * 0.1;
        points.push(TelemetryPoint {
            index: i,
            timestamp_utc_ms: 1_729_000_000_000i64 + (elapsed_s * 1000.0) as i64,
            timestamp_iso8601: format!("2026-10-28T12:00:{:02}.000Z", i / 10),
            elapsed_s,
            fly_time_s: elapsed_s,
            latitude: 47.6062 + (i as f64 * 0.00001),
            longitude: -122.3321 + (i as f64 * 0.00001),
            altitude_msl: 120.0 + (i as f64 * 0.1),
            altitude_agl: 50.0,
            altitude_baro: 50.0,
            vps_height_m: None,
            ground_speed_mps: 10.0,
            speed_3d_mps: 10.0,
            climb_rate_mps: 0.1,
            vel_n: 10.0,
            vel_e: 0.0,
            vel_d: -0.1,
            course_deg: 45.0,
            pitch_deg: 2.0,
            roll_deg: 0.0,
            yaw_deg: 45.0,
            heading_deg: 45.0,
            gimbal_pitch_deg: -30.0,
            gimbal_roll_deg: 0.0,
            gimbal_yaw_deg: 0.0,
            gimbal_mode: "Follow".to_string(),
            rc_aileron: 0.0,
            rc_elevator: 0.0,
            rc_throttle: 0.5,
            rc_rudder: 0.0,
            rc_mode_switch: "P".to_string(),
            rc_signal_quality: 100,
            battery_pct: 90,
            battery_voltage_mv: 15400,
            battery_temp_c: 32.0,
            battery_current_a: Some(5.0),
            cell_voltages_mv: vec![3850, 3850, 3850, 3850],
            cell_deviation_mv: 0,
            gps_satellites: 16,
            gps_level: 5,
            flight_mode: "P-GPS".to_string(),
            ground_state: "Airborne".to_string(),
            is_motor_on: true,
            is_failsafe_active: false,
            app_warning: None,
            app_tip: None,
        });
    }

    let metadata = FlightMetadata {
        log_type: "DJI_TXT_V12".to_string(),
        version: 12,
        duration_seconds: 59.9,
        flight_duration_seconds: 59.9,
        total_distance_meters: 600.0,
        total_records: 600,
        ..Default::default()
    };

    FlightDataset {
        metadata,
        points,
        events: vec![],
    }
}

