// ============================================================================
// 1. Boundary Condition Tests
// ============================================================================

#[tokio::test]
async fn test_boundary_empty_dataset() {
    let state = AppState::new_with_dataset(mock_empty_dataset());
    let app = build_app(state);

    // 1. GET /api/v1/flight/info on empty dataset
    let req = Request::builder()
        .method("GET")
        .uri("/api/v1/flight/info")
        .body(Body::empty())
        .unwrap();

    let res = app.clone().oneshot(req).await.unwrap();
    assert_eq!(res.status(), StatusCode::OK);
    let bytes = res.into_body().collect().await.unwrap().to_bytes();
    let info: FlightInfoResponse = serde_json::from_slice(&bytes).unwrap();
    assert!(info.loaded);
    assert_eq!(info.metadata.total_records, 0);
    assert!(info.bounds.is_none());

    // 2. GET /api/v1/flight/points on empty dataset
    let req2 = Request::builder()
        .method("GET")
        .uri("/api/v1/flight/points")
        .body(Body::empty())
        .unwrap();

    let res2 = app.clone().oneshot(req2).await.unwrap();
    assert_eq!(res2.status(), StatusCode::OK);
    let bytes2 = res2.into_body().collect().await.unwrap().to_bytes();
    let pts: ColumnarPointsResponse = serde_json::from_slice(&bytes2).unwrap();
    assert_eq!(pts.count, 0);
    assert!(pts.latitudes.is_empty());

    // 3. GET /api/v1/flight/points with time window on empty dataset
    let req3 = Request::builder()
        .method("GET")
        .uri("/api/v1/flight/points?start=0.0&end=10.0&rate=1.0")
        .body(Body::empty())
        .unwrap();

    let res3 = app.oneshot(req3).await.unwrap();
    assert_eq!(res3.status(), StatusCode::OK);
    let bytes3 = res3.into_body().collect().await.unwrap().to_bytes();
    let pts3: ColumnarPointsResponse = serde_json::from_slice(&bytes3).unwrap();
    assert_eq!(pts3.count, 0);
}

#[tokio::test]
async fn test_boundary_single_point_negative_altitude() {
    let state = AppState::new_with_dataset(mock_single_point_dataset());
    let app = build_app(state);

    // 1. GET /api/v1/flight/info
    let req = Request::builder()
        .method("GET")
        .uri("/api/v1/flight/info")
        .body(Body::empty())
        .unwrap();

    let res = app.clone().oneshot(req).await.unwrap();
    assert_eq!(res.status(), StatusCode::OK);
    let bytes = res.into_body().collect().await.unwrap().to_bytes();
    let info: FlightInfoResponse = serde_json::from_slice(&bytes).unwrap();
    assert!(info.loaded);
    let bounds = info.bounds.expect("Single point must have valid bounds");
    assert_eq!(bounds.min_latitude, bounds.max_latitude);
    assert_eq!(bounds.min_longitude, bounds.max_longitude);
    assert_eq!(bounds.min_altitude_msl, -430.5);
    assert_eq!(bounds.max_altitude_msl, -430.5);

    // 2. GET /api/v1/flight/points
    let req2 = Request::builder()
        .method("GET")
        .uri("/api/v1/flight/points")
        .body(Body::empty())
