    let res2 = app.oneshot(req2).await.unwrap();
    assert_eq!(res2.status(), StatusCode::OK);
    let bytes2 = res2.into_body().collect().await.unwrap().to_bytes();
    let pts: ColumnarPointsResponse = serde_json::from_slice(&bytes2).unwrap();
    assert_eq!(pts.count, 1);
    assert_eq!(pts.altitudes_msl[0], -430.5);
    assert_eq!(pts.altitudes_agl[0], -2.0);
}

