    let pts2: ColumnarPointsResponse = serde_json::from_slice(&bytes2).unwrap();
    assert_eq!(pts2.count, 0);

    // 3. Extremely high decimation rate (e.g. rate=1000.0 Hz)
    let req3 = Request::builder()
        .method("GET")
        .uri("/api/v1/flight/points?rate=1000.0")
        .body(Body::empty())
        .unwrap();
    let res3 = app.clone().oneshot(req3).await.unwrap();
    assert_eq!(res3.status(), StatusCode::OK);

    // 4. Non-numeric parameter strings -> HTTP 400
    let req4 = Request::builder()
        .method("GET")
        .uri("/api/v1/flight/points?rate=invalid_number")
        .body(Body::empty())
        .unwrap();
    let res4 = app.clone().oneshot(req4).await.unwrap();
    assert_eq!(res4.status(), StatusCode::BAD_REQUEST);

    // 5. Inverted bounds -> HTTP 400
    let req5 = Request::builder()
        .method("GET")
        .uri("/api/v1/flight/points?start=100.0&end=50.0")
        .body(Body::empty())
        .unwrap();
    let res5 = app.oneshot(req5).await.unwrap();
    assert_eq!(res5.status(), StatusCode::BAD_REQUEST);
}

// ============================================================================
// 3. Ingestion Stress Tests
// ============================================================================

#[tokio::test]
async fn test_ingestion_truncated_and_corrupt_buffers() {
    let state = AppState::new_empty();
    let app = build_app(state);

    // 1. Exactly 1 byte [0x55] (DAT magic)
    let req1 = Request::builder()
        .method("POST")
        .uri("/api/v1/upload")
        .header(header::CONTENT_TYPE, "application/octet-stream")
        .body(Body::from(vec![0x55]))
        .unwrap();
    let res1 = app.clone().oneshot(req1).await.unwrap();
    assert_eq!(res1.status(), StatusCode::BAD_REQUEST);

    // 2. Exactly 8 bytes [0x55, ...] (DAT magic truncated < 9)
    let req2 = Request::builder()
        .method("POST")
        .uri("/api/v1/upload")
        .header(header::CONTENT_TYPE, "application/octet-stream")
        .body(Body::from(vec![0x55; 8]))
        .unwrap();
    let res2 = app.clone().oneshot(req2).await.unwrap();
    assert_eq!(res2.status(), StatusCode::BAD_REQUEST);

    // 3. Exactly 99 bytes (TXT truncated < 100)
    let req3 = Request::builder()
        .method("POST")
        .uri("/api/v1/upload")
        .header(header::CONTENT_TYPE, "application/octet-stream")
        .body(Body::from(vec![0x10; 99]))
        .unwrap();
    let res3 = app.clone().oneshot(req3).await.unwrap();
    assert_eq!(res3.status(), StatusCode::BAD_REQUEST);

    // 4. Corrupted 9-byte DAT frame with invalid CRC
    let bad_dat = vec![0x55, 0x09, 0x00, 0x01, 0x00, 0x00, 0x00, 0xFF, 0xFF];
    let req4 = Request::builder()
        .method("POST")
        .uri("/api/v1/upload")
        .header(header::CONTENT_TYPE, "application/octet-stream")
        .body(Body::from(bad_dat))
        .unwrap();
    let res4 = app.clone().oneshot(req4).await.unwrap();
    assert_eq!(res4.status(), StatusCode::BAD_REQUEST);

    // 5. Malformed multipart boundary
    let req5 = Request::builder()
        .method("POST")
        .uri("/api/v1/upload")
        .header(header::CONTENT_TYPE, "multipart/form-data; boundary=myboundary")
        .body(Body::from("not a valid multipart body"))
        .unwrap();
    let res5 = app.clone().oneshot(req5).await.unwrap();
    assert_eq!(res5.status(), StatusCode::BAD_REQUEST);

    // 6. Multipart with empty parts
    let empty_multipart = "--bound\r\nContent-Disposition: form-data; name=\"file\"; filename=\"empty.txt\"\r\n\r\n\r\n--bound--\r\n";
    let req6 = Request::builder()
        .method("POST")
        .uri("/api/v1/upload")
        .header(header::CONTENT_TYPE, "multipart/form-data; boundary=bound")
        .body(Body::from(empty_multipart))
        .unwrap();
    let res6 = app.oneshot(req6).await.unwrap();
    assert_eq!(res6.status(), StatusCode::BAD_REQUEST);
}

