// ============================================================================

#[tokio::test]
async fn test_ws_multi_client_fanout() {
    let dataset = mock_canonical_dataset();
    let state = AppState::new_with_dataset(dataset);
    let app = build_app(state);

    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();

    let server_task = tokio::spawn(async move {
        axum::serve(listener, app).await.unwrap();
    });

    let ws_url = format!("ws://{}/api/v1/ws", addr);

    // Connect Client 1, Client 2, Client 3
    let (mut c1_stream, _) = connect_async(&ws_url).await.unwrap();
    let (mut c2_stream, _) = connect_async(&ws_url).await.unwrap();
    let (mut c3_stream, _) = connect_async(&ws_url).await.unwrap();

    // Client 1 sends seek to index 100
    c1_stream
        .send(Message::Text(r#"{"type":"seek","index":100}"#.into()))
        .await
        .unwrap();

    // Verify ALL 3 clients receive the broadcast frame for index 100
    for (i, stream) in [&mut c1_stream, &mut c2_stream, &mut c3_stream]
        .into_iter()
        .enumerate()
    {
        let msg = stream
            .next()
            .await
            .expect("Expected frame")
            .expect("WS error");
        let server_msg: WsServerMessage = serde_json::from_str(msg.to_text().unwrap()).unwrap();
        match server_msg {
            WsServerMessage::Frame(frame) => {
                assert_eq!(
                    frame.index, 100,
                    "Client {} expected index 100, got {}",
                    i + 1,
                    frame.index
                );
            }
            other => panic!("Client {} expected Frame, got {:?}", i + 1, other),
        }
    }

    server_task.abort();
}

#[tokio::test]
async fn test_ws_boundary_seeks_and_seek_time() {
    let dataset = mock_canonical_dataset();
    let state = AppState::new_with_dataset(dataset);
    let app = build_app(state);

    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();

    let server_task = tokio::spawn(async move {
        axum::serve(listener, app).await.unwrap();
    });

    let ws_url = format!("ws://{}/api/v1/ws", addr);
    let (mut ws_stream, _) = connect_async(&ws_url).await.unwrap();

    // 1. Seek to index 0 (lower bound)
    ws_stream
        .send(Message::Text(r#"{"type":"seek","index":0}"#.into()))
        .await
        .unwrap();
    let msg = ws_stream.next().await.unwrap().unwrap();
    let server_msg: WsServerMessage = serde_json::from_str(msg.to_text().unwrap()).unwrap();
    if let WsServerMessage::Frame(f) = server_msg {
        assert_eq!(f.index, 0);
    } else {
        panic!("Expected frame");
    }

    // 2. Seek to huge index (upper bound clamping)
    ws_stream
        .send(Message::Text(r#"{"type":"seek","index":18446744073709551615}"#.into()))
        .await
        .unwrap();
    let msg = ws_stream.next().await.unwrap().unwrap();
    let server_msg: WsServerMessage = serde_json::from_str(msg.to_text().unwrap()).unwrap();
    if let WsServerMessage::Frame(f) = server_msg {
        assert_eq!(f.index, 599);
    } else {
        panic!("Expected frame");
    }

    // 3. Seek to negative elapsed_s (clamped to 0.0)
    ws_stream
        .send(Message::Text(r#"{"type":"seek_time","elapsed_s":-100.0}"#.into()))
        .await
        .unwrap();
    let msg = ws_stream.next().await.unwrap().unwrap();
    let server_msg: WsServerMessage = serde_json::from_str(msg.to_text().unwrap()).unwrap();
    if let WsServerMessage::Frame(f) = server_msg {
        assert_eq!(f.index, 0);
    } else {
        panic!("Expected frame");
    }

    // 4. Seek to huge elapsed_s (clamped to final point)
    ws_stream
        .send(Message::Text(r#"{"type":"seek_time","elapsed_s":99999.0}"#.into()))
        .await
        .unwrap();
    let msg = ws_stream.next().await.unwrap().unwrap();
    let server_msg: WsServerMessage = serde_json::from_str(msg.to_text().unwrap()).unwrap();
    if let WsServerMessage::Frame(f) = server_msg {
        assert_eq!(f.index, 599);
    } else {
        panic!("Expected frame");
    }

    // 5. Alternate action JSON format ("action": "seek")
    ws_stream
        .send(Message::Text(r#"{"action":"seek","index":77}"#.into()))
        .await
        .unwrap();
    let msg = ws_stream.next().await.unwrap().unwrap();
    let server_msg: WsServerMessage = serde_json::from_str(msg.to_text().unwrap()).unwrap();
    if let WsServerMessage::Frame(f) = server_msg {
        assert_eq!(f.index, 77);
    } else {
        panic!("Expected frame");
    }

    server_task.abort();
}

#[tokio::test]
async fn test_ws_rapid_timeline_scrubbing_stress() {
    let dataset = mock_canonical_dataset();
    let state = AppState::new_with_dataset(dataset);
    let app = build_app(state);

    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();

    let server_task = tokio::spawn(async move {
        axum::serve(listener, app).await.unwrap();
    });

    let ws_url = format!("ws://{}/api/v1/ws", addr);
    let (mut ws_stream, _) = connect_async(&ws_url).await.unwrap();

    // Send a burst of 100 scrub requests in rapid succession
    let burst_count = 100;
    for i in 0..burst_count {
        let msg = format!(r#"{{"type":"scrub","index":{},"timestamp_ms":1000}}"#, i);
        ws_stream.send(Message::Text(msg)).await.unwrap();
    }

    // Receive the responses
    let mut received_frames = 0;
    for _ in 0..burst_count {
        match tokio::time::timeout(std::time::Duration::from_millis(500), ws_stream.next()).await {
            Ok(Some(Ok(Message::Text(txt)))) => {
                let parsed: Result<WsServerMessage, _> = serde_json::from_str(&txt);
                if let Ok(WsServerMessage::Frame(_)) = parsed {
                    received_frames += 1;
                }
            }
            Ok(Some(Ok(Message::Close(_)))) => {
                panic!("WebSocket closed unexpectedly during rapid scrubbing");
            }
            _ => break,
        }
    }

    assert_eq!(received_frames, burst_count, "All 100 scrub frames must be received");

    // Ping should still succeed cleanly after rapid burst
    ws_stream.send(Message::Text(r#"{"type":"ping"}"#.into())).await.unwrap();
    let pong = tokio::time::timeout(std::time::Duration::from_millis(500), ws_stream.next())
        .await
        .expect("Timeout waiting for pong")
        .expect("None")
        .unwrap();
    assert_eq!(
        serde_json::from_str::<WsServerMessage>(pong.to_text().unwrap()).unwrap(),
        WsServerMessage::Pong
    );

    server_task.abort();
}

